"""Writes evals/report.md from rules/, det_results.json, controls.jsonl, pairwise.jsonl and judge/results/status.json."""
import json, os, re, glob, collections, datetime
B = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
idx = json.load(open(f'{B}/rules/index.json'))
rules = [r for f in sorted(glob.glob(f'{B}/rules/[a-e]_*.json')) for r in json.load(open(f))['rules']]
d = json.load(open(f'{B}/evals/det_results.json')); v0p = f'{B}/evals/det_results_v0_pretuning.json'
v0 = json.load(open(v0p)) if os.path.exists(v0p) else None
ctrls = [json.loads(l) for l in open(f'{B}/evals/controls.jsonl')]
pw = [json.loads(l) for l in open(f'{B}/evals/pairwise.jsonl')]
js = json.load(open(f'{B}/judge/results/status.json')) if os.path.exists(f'{B}/judge/results/status.json') else {'ran': False, 'reason': 'runner not invoked'}
cases = [json.loads(l) for l in open(f'{B}/evals/opdp_cases.jsonl')]
FAM = {'a': 'Statute & regs', 'b': 'FDA guidance', 'c': 'FTC', 'd': 'OIG / CIA', 'e': 'PhRMA'}
def pct(a, b): return f"{100*a/b:.0f}%" if b else 'n/a'
L = [f"# Margin rulebook + eval report (auto-generated by `scripts/build.py`, {datetime.date.today()})", "",
     "Method: see `method.md` (Crosby's three eval principles, adapted). All synthetic content is labeled `synthetic: true`. Nothing here was sent anywhere.", "",
     "## 1. Rulebook", "", "| Family | Deterministic | Judgment | Total | With >=1 OPDP case |", "|---|---|---|---|---|"]
for f in 'abcde':
    rs = [r for r in rules if r['id'][0] == f.upper()]
    L.append(f"| ({f}) {FAM[f]} | {sum(r['check_type']=='deterministic' for r in rs)} | {sum(r['check_type']=='judgment' for r in rs)} | {len(rs)} | {sum(bool(r['opdp_case_ids']) for r in rs)} |")
qc = collections.Counter(r.get('quote_check') for r in rules)
L += [f"| **Total** | {sum(r['check_type']=='deterministic' for r in rules)} | {sum(r['check_type']=='judgment' for r in rules)} | {len(rules)} | {sum(bool(r['opdp_case_ids']) for r in rules)} |", "",
      f"Verbatim quotes checked against archived source text (`rules/sources/`): {dict(qc)}.", ""]
pw_rules = collections.Counter(p['rule_id'] for p in pw)
nocase = [r for r in rules if not r['opdp_case_ids']]
L += ["### Rule coverage", "", f"- Rules linked to >=1 OPDP case: {len(rules)-len(nocase)}/{len(rules)}. Rules with a pairwise item: {len(pw_rules)}/{len(rules)}.",
      f"- Rules with **no OPDP case and no pairwise item** ({sum(1 for r in nocase if r['id'] not in pw_rules)}): " + ', '.join(r['id'] for r in nocase if r['id'] not in pw_rules),
      f"- Rules with no OPDP case but covered only by synthetic near-miss pairs: " + (', '.join(r['id'] for r in nocase if r['id'] in pw_rules) or 'none'),
      "- OPDP letters only exercise FDA promo rules; FTC/OIG/PhRMA rules have no real-world positives in this set (OPDP letters do not cite them).", ""]
# deterministic recall
L += ["## 2. Deterministic checks vs OPDP deterministic cases (recall)", "",
      f"{d['n_det_cases']} deterministic cases; {d['cases_with_linked_rule']} linked to >=1 deterministic rule. Fixtures are built only from what the letter states "
      "(quoted fragments the letter attributes to the piece + facts the letter states, see `evals/fixtures.py`). "
      f"**Case-level recall** (case had >=1 evaluable, non-tautological linked check; did any fire?): **{d['case_level']['caught']}/{d['case_level']['evaluable']} = {pct(d['case_level']['caught'], d['case_level']['evaluable'])}**.", "",
      "Recall per check = fired / evaluable (evaluable = check could run on letter-derived inputs; `needs_input` = letter text can't supply what the check needs, e.g. airtime, supers, full risk list).", "",
      "| Check | Group | Linked cases | Evaluable | Fired | Recall | Needs input / N/A |", "|---|---|---|---|---|---|---|"]
order = {'claim_level': 0, 'whole_piece': 1, 'tautological': 2}
for k, v in sorted(d['per_check'].items(), key=lambda x: (order[x[1]['group']], -x[1]['linked'])):
    L.append(f"| {k} | {v['group']} | {v['linked']} | {v['evaluable']} | {v['fired']} | {pct(v['fired'], v['evaluable'])} | {v['needs_input']} / {v['not_applicable']} |")
agg = collections.defaultdict(lambda: [0, 0])
for k, v in d['per_check'].items(): agg[v['group']][0] += v['fired']; agg[v['group']][1] += v['evaluable']
ni = sum(v['needs_input'] for v in d['per_check'].values())
L += ["", "Pooled: " + '; '.join(f"{g} {a}/{b} ({pct(a, b)})" for g, (a, b) in agg.items()) + f"; check-case pairs not evaluable from letter text: {ni}.", "",
      "How to read this:",
      "- **claim_level** (lexical/structural triggers on the claim itself) is the informative number.",
      "- **whole_piece** checks (risk present, established name, MedWatch, etc.) are run on letter *excerpts*; a hit is only semi-informative because the letter already tells us the element was absent.",
      "- **tautological** (`form_2253`): the fixture encodes the letter's finding, so 100% is by construction. Reported, not counted.",
      "- Not evaluable: dual modality, super legibility/reading speed, audio pacing, risk-after-close, risk coverage (need the asset or a full PI risk list).",
      "- **Circularity caveat:** the checks and lexicons were written while looking at these same letters; there is no held-out split. Treat recall as an upper bound on in-distribution recall, not a generalization estimate.", ""]
miss = {k: v['cases_missed'] for k, v in d['per_check'].items() if v['cases_missed'] and v['group'] != 'tautological'}
L += ["Misses (for error analysis): " + '; '.join(f"{k}: {', '.join(m)}" for k, m in miss.items()), ""]
# controls / FP
c = d['controls']; gen = collections.Counter(k['generator'] for k in ctrls); cn = collections.Counter(k['context_needed'] for k in ctrls)
L += ["## 3. Negative controls (synthetic compliant rewrites) and false positives", "",
      f"`evals/controls.jsonl`: {len(ctrls)} controls ({sum(k['source_check_type']=='judgment' for k in ctrls)} = every judgment case; {sum(k['source_check_type']=='deterministic' for k in ctrls)} = stratified seeded sample of deterministic cases). "
      f"Generators: {dict(gen)}. None human-reviewed. `context_needed` (what a reviewer needs beyond the text to confirm the fix; Crosby's synthesis-vs-missing-context split): {dict(cn)}.", "",
      f"**Targeted false positives** (control still trips the check linked to the problem it fixed): " + ', '.join(f"{k} {v['fired']}/{v['evaluated']}" for k, v in c['targeted'].items() if v['evaluated']) + ".", ""]
tf = sum(v['fired'] for v in c['targeted'].values()); te = sum(v['evaluated'] for v in c['targeted'].values())
L += [f"Pooled targeted FP: {tf}/{te} ({pct(tf, te)}). Every targeted fire was read by hand; explanations in section 6.", "",
      f"**Claim-level checks on all controls** (any claim-level fire on {c['with_any_claim_level_fail']}/{c['n']} controls = {pct(c['with_any_claim_level_fail'], c['n'])}):", "",
      "| Check | Fired / evaluated (after tuning) | Before tuning (v0) |", "|---|---|---|"]
for k, v in sorted(c['per_check'].items()):
    if c['groups'][k] != 'claim_level': continue
    o = v0['controls']['per_check'].get(k) if v0 else None
    L.append(f"| {k} | {v['fired']}/{v['evaluated']} ({pct(v['fired'], v['evaluated'])}) | {(str(o['fired']) + '/' + str(o['evaluated'])) if o else 'n/a'} |")
L += ["", "Trigger checks are designed to route text to a human or a substantiation lookup, so a fire on compliant text costs review time; it is not an approval error. "
      "Tuning between v0 and now (all generic, none case-specific): negation handling ('not cured', 'no studies have shown ... safer'), placebo/vehicle/baseline comparators no longer count as comparative claims, "
      "'only' requires an exclusivity construction ('the only', 'only FDA-approved'), the investigational-code regex no longer matches 'FDA-2253', '50 x 10^9/L' is not a relative multiplier, "
      "risk-link labels ('View Important Safety Info') no longer count as risk content, empty-text fixtures return needs_input. The v0→v1 change cost one recall hit: exclusivity_claim lost the 'another ... option' pattern. "
      "Because tuning used these controls, the after-tuning FP numbers are optimistic.", "",
      "Whole-piece checks (MedWatch, adequate provision, cost info, Rx indicator, established name, risk present, etc.) fire on most controls because controls are claim excerpts, not complete pieces; those rates are not FP estimates and are omitted here (raw numbers in `det_results.json`).", ""]
# pairwise
k = collections.Counter(p['kind'] for p in pw); w = collections.Counter(p['expected_winner'] for p in pw)
L += ["## 4. Pairwise set", "", f"`evals/pairwise.jsonl`: {len(pw)} items: {k['easy']} easy (letter-quoted original vs synthetic rewrite) + {k['near_miss']} near-miss (hand-authored, fictional products, one subtle difference each). "
      f"A/B order seeded-random (expected winner A={w['A']}, B={w['B']}). Each item carries one rule question with pass/fail anchors from the rulebook, `expected_winner`, and `expected_approvable` per side "
      "(the violating side is always false; the compliant side is true for near-misses and unknown (null) for easy pairs, since rewrites contain [placeholders]). "
      f"{sum(1 for p in pw if p['kind']=='easy')} of {len(ctrls)} controls became pairs; omitted: originals that are only the letter's description of an omission/process (no piece text to compare).", "",
      "Easy pairs are easier than Crosby's agent-draft vs lawyer-final pairs (the original is a known violation and the rewrite often contains bracketed placeholders), so they only set a floor: a judge that can't win these isn't ready.", ""]
L += ["## 5. Judge", "", "Prompts: `judge/pairwise_prompt.md`, `judge/single_prompt.md`. Runner: `judge/run_judge.py` (OpenRouter by default; responses cached in `judge/results/cache.jsonl`; $3 spend cap). Raw verdicts: `judge/results/raw.jsonl`.", ""]
raw = [json.loads(l) for l in open(f'{B}/judge/results/raw.jsonl')] if os.path.exists(f'{B}/judge/results/raw.jsonl') and js.get('ran') else []
JUDGE_NOTES = json.load(open(f'{B}/judge/failure_review.json')) if os.path.exists(f'{B}/judge/failure_review.json') else {}
if js.get('ran') and raw:
    S = js['summary']; pr = js.get('pricing_per_million', {})
    def a(x): return f"{x['correct']}/{x['n']} ({pct(x['correct'], x['n'])})"
    L += [f"**Model:** `{js['model']}` via OpenRouter ({'free tier' if js.get('free') else 'paid'}; listed price ${pr.get('input')}/M input, ${pr.get('output')}/M output). "
          f"**Cost:** ${js.get('cumulative_cost_usd', 0):.4f} total across all judge runs (OpenRouter-reported per-call cost, summed from the response cache; by model: {js.get('cumulative_cost_usd_by_model')}); last run ${js.get('cost_usd_this_run', 0):.4f} for {js.get('api_calls_this_run')} new calls + {js.get('cache_hits')} cache hits. Last run finished {js['at']}. " + (f"Note: {js['note']} " if js.get('note') else '')
          + (f"Stopped early: {js['stopped']}. " if js.get('stopped') else '') + "Model selection: the runner probes free models first (5 real pairwise prompts; needs >=4 parseable answers); "
          "see the note above for which model was used and why.", "",
          "Every pair was judged in both A/B orders (original order and swapped), so each pair contributes 2 verdicts.", ""]
    for ph, title in (('calibrate', 'Calibration on known-winner pairs (easy: letter-cited original vs synthetic rewrite)'), ('nearmiss', 'Near-miss pairs (fictional, one subtle difference)')):
        x = S[ph]; pb = x['pairs_both_orders']; fl = x['approvable_flags']
        L += [f"### {title}", "", f"- Accuracy: **{a(x['overall'])}** verdicts; unparseable/errored: {x['errors']}.",
              f"- Position bias: accuracy when correct answer is A = {a(x['when_correct_is_A'])}; when B = {a(x['when_correct_is_B'])}; judge chose A in {x['chose_A']}/{x['n_answered']} ({pct(x['chose_A'], x['n_answered'])}). "
              f"Pairs judged both orders: {pb['n']}; correct in both = {pb['both_correct']}; verdict flipped with order = {pb['order_flip']}.",
              "- By rule family: " + '; '.join(f"{FAM[f.lower()]} {a(v)}" for f, v in x['by_family'].items()),
              "- By rule check_type: " + '; '.join(f"{k} {a(v)}" for k, v in x['by_check_type'].items() if v['n']),
              f"- 'Approvable as is' flags in the pairwise answer: violating side marked not approvable {fl.get('violating_flagged_not_approvable',0)}/{fl.get('violating_n',0)}; compliant side marked approvable {fl.get('compliant_marked_approvable',0)}/{fl.get('compliant_n',0)}"
              + (" (easy-pair rewrites contain [placeholders], so 'not approvable' there is often correct)." if ph == 'calibrate' else '.'), ""]
        if ph == 'calibrate':
            c_ok = x['overall']['correct'] / max(1, x['overall']['n'])
            L += [f"Readiness gate (method.md: a judge that fails the obvious cases isn't used on close calls; threshold 90%): **{'PASSED' if c_ok >= 0.9 else 'FAILED'}** ({c_ok:.1%}).", ""]
        if ph == 'nearmiss':
            L += ["| Pair | Rule | Correct (orig order) | Correct (swapped) |", "|---|---|---|---|"]
            nm = collections.defaultdict(dict)
            for r in raw:
                if r['phase'] == 'nearmiss': nm[(r['id'], r['rule_id'])][r['order']] = ('yes' if r.get('out') and r['out'].get('winner') == r['expected'] else ('ERR' if not r.get('out') else 'NO'))
            for (i, rid), v in sorted(nm.items()): L.append(f"| {i} | {rid} | {v.get('orig','')} | {v.get('swapped','')} |")
            L += [""]
    sg = S['single']
    L += ["### Single-item 'would you sign off on this rule as is' judging", "",
          f"- Near-miss violating versions judged FAIL: {a(sg['near_miss_violating'])}; near-miss compliant versions judged PASS: {a(sg['near_miss_compliant'])}.",
          f"- Easy pairs: letter-cited originals judged FAIL: {a(sg['easy_violating'])}; synthetic rewrites judged PASS: {a(sg['easy_compliant'])} (rewrites contain [placeholders] and visual notes, so a FAIL/missing-context there is often reasonable).",
          f"- Judge set missing_context=true on {sg['missing_context_flagged']} single-item verdicts; unparseable/errored: {sg['errors']}.", ""]
    fails = [r for r in raw if r['phase'] in ('calibrate', 'nearmiss') and r.get('out') and r['out'].get('winner') != r['expected']]
    L += ["### Pairwise failures, read and characterized", "", f"{len(fails)} wrong pairwise verdicts. Categories: bad_rewrite = our 'compliant' side isn't actually better on this rule; "
          "judge_error = judge misread or missed the decisive difference; ambiguous_item = rule question/label facts underdetermine the answer; position = wrong only in one order.", ""]
    cats = collections.Counter()
    for r in sorted(fails, key=lambda r: (r['phase'], r['id'], r['order'])):
        n = JUDGE_NOTES.get(f"{r['id']}|{r['order']}") or JUDGE_NOTES.get(r['id']) or {'cat': 'unreviewed', 'note': ''}
        cats[n['cat']] += 1
        L.append(f"- [{r['phase']}] {r['id']} ({r['rule_id']}, {r['order']}): judge reason: \"{(r['out'].get('reason') or '')[:220]}\" → **{n['cat']}**. {n['note']}")
    L += ["", "Failure categories: " + ', '.join(f"{k} {v}" for k, v in cats.items()), ""]
    nmf = [r for r in raw if r['phase'] == 'single' and r['kind'] == 'near_miss' and r.get('out') and r['out'].get('verdict') != r['expected']]
    L += ["### Single-item near-miss failures, read and characterized", ""]
    for r in nmf:
        n = JUDGE_NOTES.get(f"{r['id']}|single", {'cat': 'unreviewed', 'note': ''})
        L.append(f"- {r['id']} ({r['rule_id']}, {r['side_is']} side judged {r['out'].get('verdict')}): \"{(r['out'].get('reason') or '')[:200]}\" → **{n['cat']}**. {n['note']}")
    ev = [r for r in raw if r['phase'] == 'single' and r['kind'] == 'easy' and r['side_is'] == 'violating' and r.get('out') and r['out'].get('verdict') != r['expected']]
    L += ["", f"Easy originals judged PASS ({len(ev)}; {sum(bool(r['out'].get('missing_context')) for r in ev)} of them flagged missing_context): mostly an **item-rule mismatch**. "
          "`make_pairwise.py` assigns each easy pair the first judgment rule linked to its case, so emotional taglines or visual-only problems get asked a data-support question "
          "(B-CFL-03, A-202-E5-01), and the quoted excerpt alone doesn't trigger it. Two are judge leniency: Recorlev's 'will help your doctor avoid side effects' passed under a lexicon-style "
          "minimization rule, and Gvoke's 'Easy to know you did it right' passed under an efficacy rule. Fix: give each easy pair the rule that matches the letter's category.", "",
          f"Easy rewrites judged FAIL: {sg['easy_compliant']['n'] - sg['easy_compliant']['correct']} (missing_context on most). Expected, because rewrites carry [placeholders]; this is not a judge error signal.", "",
          f"Empty output: the model returned no content for every call on {', '.join(sorted({r['id'] for r in raw if not r.get('out')}))} (Jeuveau botulinum-toxin newsletter, 4 calls). Likely provider-side safety filtering; those calls are excluded from accuracy.", ""]
    v1p = f'{B}/judge/results/status_v1.json'
    if os.path.exists(v1p):
        v1 = json.load(open(v1p))['summary']
        L += ["### v1 → v2 (fixes made after reading v1 failures; disclosed because they were made after seeing results)", "",
              f"- v1: calibration {a(v1['calibrate']['overall'])}; near-miss pairwise {a(v1['nearmiss']['overall'])}; single near-miss violating→FAIL {a(v1['single']['near_miss_violating'])}, compliant→PASS {a(v1['single']['near_miss_compliant'])}.",
              "- Fixes: (1) deterministic-rule anchors no longer paste the check's metadata logic. In v1 the judge failed compliant text because 'meta.substantiated_claims' / 'meta.reference_checks' were absent (NM-15, NM-21). "
              "(2) Two near-miss pairs were mapped to the wrong OIG rule (NM-24 venue/alcohol → D-SP-01, was D-SP-03; NM-25 repeat attendance → D-SP-03, was D-SP-04). "
              "(3) NM-23's compliant payor side lacked the material-differences statement the rule requires, so it was added (to both sides' indication framing too, so only the disclosures differ). "
              "(4) A lenient JSON parser now handles answers with unescaped quotes inside 'reason' (13 v1 calibration answers were unparseable).",
              f"- v2 (headline numbers above): calibration {a(S['calibrate']['overall'])}; near-miss pairwise {a(S['nearmiss']['overall'])}; single near-miss violating→FAIL {a(sg['near_miss_violating'])}, compliant→PASS {a(sg['near_miss_compliant'])}.", ""]
else:
    L += [f"**Not run.** {re.sub(r'Your team [0-9a-f-]+ has', 'Account has', js.get('reason', ''))} (checked {js.get('at','')}). No judge results are reported or implied.", ""]
REVIEWED = {
 ('comparative_claim', 'CTRL-UL-20250909-188908-v1'): 'LLM rewrite keeps "Skyrizi vs Stelara" from a real head-to-head study; the trigger asks for substantiation on file (passes once meta.substantiated_claims lists it). Working as designed.',
 ('endorser_user', 'CTRL-UL-20250909-188723-v1'): 'First-person "I take it" fires until bona fide-user verification is recorded in metadata. Working as designed.',
 ('endorser_user', 'CTRL-UL-20250909-188756-v1'): 'Same as above (first-person testimonial, no verification on file).',
 ('exclusivity_claim', 'CTRL-UL-20260526-192843-v1'): 'LLM rewrite kept "the only FDA-approved enzyme replacement therapy"; the letter cited indication broadening, not exclusivity. The flag asks for verification, which is reasonable.',
 ('fda_approval_misuse', 'CTRL-UL-20260526-192843-v1'): 'Same text ("only FDA-approved"). Verification flag, not an error.',
 ('guideline_citation', 'CTRL-UL-20250909-188900-v2'): 'Any NCCN citation routes to a version/wording check. Working as designed.',
 ('posthoc_language', 'CTRL-UL-20260624-193472-v1'): 'The LLM "compliant" rewrite still presents post hoc results (now labeled post hoc). The check is right and the control is flawed. Evidence that LLM controls need human review.',
 ('testimonial_typicality', 'CTRL-UL-20250909-188756-v1'): 'Agent rewrite added "Individual results vary" to a testimonial; FTC 255.2(b) says that does not disclose generally expected results. The flag is defensible and the control is imperfect.',
}
L += ["## 6. Hand review of targeted control fires", ""]
for k2, v in c['targeted'].items():
    for cid in v['controls_fired']: L.append(f"- {k2} / {cid}: {REVIEWED.get((k2, cid), 'NOT YET REVIEWED (new since last hand review)')}")
L += ["", "Net: 0 clear check errors among targeted fires; 6 are by-design verification triggers; 2 are flawed/imperfect controls.", "",
      "## 7. Gaps", "",
      ("- **Judge:** one model (claude-haiku-5.5; v1 run, then v2 after item/prompt fixes), no human agreement baseline; calibration pairs are easy by construction, so the near-miss and single-item numbers matter more. The 82 LLM-drafted controls came from an xAI model and the judge is an Anthropic model, so the judge is not grading its own rewrites. The judge model was chosen because the free model was rate-limited, not because it was evaluated as best." if js.get('ran') else "- **Judge unrun.** Pairwise/single-item judge accuracy, position bias and 'approvable as is' agreement are unknown."),
      "- **No human labels.** Controls (82 LLM-drafted, 94 agent-authored) and near-miss pairs are unreviewed by a regulatory reviewer. Crosby's method hinges on expert comparisons; this set is a scaffold until the owner's MLR team reviews it. At least one LLM control (Vyepti post hoc) is not actually compliant.",
      "- **Circularity:** checks were tuned while viewing these letters and controls; no held-out split. Next step: freeze checks and score on letters issued after 2026-10-07, or hold out a random 30% of letters.",
      "- **Visual/audiovisual cases** (distraction, dual modality, super legibility, pacing, airtime): checks exist but need asset metadata (supers, timings, wpm); letters can't supply it, so they're not evaluable here. Needs real assets from PromoMats.",
      "- **Risk coverage** (37 linked cases) needs a structured PI risk list per product; none loaded. This is the biggest deterministic blind spot.",
      "- **Sources not fetched/verified:** 21 CFR 314.81 text (cited as letters cite it); Brief Summary 2015 draft quote unchecked against source; revised 'Addressing Misinformation' draft (supersedes 2014) and the June 2026 payor Q&A draft revision not fetched; ACCME Standards, GPP 2022, HIPAA patient-story authorization not done; ex-US codes (EFPIA, ABPI, PMCPA, IFPMA) skipped by instruction.",
      "- **FTC/OIG/PhRMA rules** have no real positives (OPDP letters don't cite them). Need FTC actions (e.g., health-claim cases), OIG/DOJ speaker-program settlements and CIA reports as positive sources.",
      f"- **Easy pairs are easy:** originals are known violations and rewrites contain [placeholders]. Near-miss pairs ({k['near_miss']}) are the meaningful judge test, but there are few and they cover only {len({p['rule_id'] for p in pw if p['kind']=='near_miss'})} rules.",
      ""]
_sum = f'{B}/evals/scoreboard/SUMMARY.md'
if os.path.exists(_sum):  # phase 3: self-improvement loop (scripts/loop.py); per-round files in evals/scoreboard/, every change in evals/ledger.jsonl
    L += ['## Self-improvement loop (phase 3)', '', 'Generated by `scripts/loop_summary.py`. Placeholder leakage noted above was removed in eval-data change E2 (see ledger).', '']
    L += [l.replace('# Loop summary', '### Loop summary').replace('## dev', '### dev').replace('## holdout', '### holdout').replace('## Ledger', '### Ledger') for l in open(_sum).read().split('\n')]
open(f'{B}/evals/report.md', 'w').write('\n'.join(L) + '\n')
print('report.md written')
